import{_ as i,o as r,c as s,j as e,a as t,a0 as a}from"./chunks/framework.CNDWyMYS.js";const m=JSON.parse('{"title":"Rockspec format","description":"","frontmatter":{},"headers":[],"relativePath":"rockspec_format.md","filePath":"rockspec_format.md"}'),n={name:"rockspec_format.md"};function l(c,o,d,u,h,p){return r(),s("div",null,[...o[0]||(o[0]=[e("h1",{id:"rockspec-format",tabindex:"-1"},[t("Rockspec format "),e("a",{class:"header-anchor",href:"#rockspec-format","aria-label":'Permalink to "Rockspec format"'},"​")],-1),e("p",null,"For number fields, strings are accepted and converted using tonumber().",-1),e("h2",{id:"package-metadata",tabindex:"-1"},[t("Package metadata "),e("a",{class:"header-anchor",href:"#package-metadata","aria-label":'Permalink to "Package metadata"'},"​")],-1),e("ul",null,[e("li",null,[e("strong",null,"rockspec_format"),t(' (string) - the file format version. Example: "1.0"')]),e("li",null,[e("strong",null,"package"),t(' (string, mandatory field) - the name of the package. Example: "LuaSocket"')]),e("li",null,[e("strong",null,"version"),t(' (string, mandatory field) - the version of the package, plus a suffix indicating the revision of the rockspec. Example: "2.0.1-1"')]),e("li",null,[e("strong",null,"description"),t(" (table) "),e("ul",null,[e("li",null,[e("strong",null,"description.summary"),t(' (string) - A one-line description of the package. Example: "Network support for the Lua language"')]),e("li",null,[e("strong",null,"description.detailed"),t(' (string) - A longer description of the package. Example: "LuaSocket is a Lua extension library that is composed by two parts: a C core that provides support for the TCP and UDP transport layers, and a set of Lua modules that add support for functionality commonly needed by applications that deal with the Internet."')]),e("li",null,[e("strong",null,"description.license"),t(' (string) - The license used by the package. A short name, such as "MIT" and "GPL-2" is preferred. Software using the same license as Lua 5.x should use "MIT".')]),e("li",null,[e("strong",null,"description.homepage"),t(' (string) - An URL for the project. This is not the URL for the tarball, but the address of a website. Example: "'),e("a",{href:"https://github.com/keplerproject/rings",target:"_blank",rel:"noreferrer"},"https://github.com/keplerproject/rings"),t('"')]),e("li",null,[e("strong",null,"description.issues_url"),t(` (string) (since 3.0) - An URL for the project's issue tracker. Example: "`),e("a",{href:"https://github.com/keplerproject/rings/issues",target:"_blank",rel:"noreferrer"},"https://github.com/keplerproject/rings/issues"),t('"')]),e("li",null,[e("strong",null,"description.maintainer"),t(" (string) - Contact information for the "),e("em",null,"rockspec"),t(' maintainer (which may or may not be the package maintainer -- contact for the package maintainer can usually be obtained through the address in the homepage field). Example: "John Doe <john@doe.gov>"')]),e("li",{"crypto,":"","network,":"","tls,":"",https:""},[e("strong",null,"description.labels"),t(" (array of strings) (since 3.0) - A list of short strings that specify labels for categorization of this rock. See the list of labels at ["),e("a",{href:"https://luarocks.org",target:"_blank",rel:"noreferrer"},"https://luarocks.org"),t("] for inspiration. Example:")])])])],-1),a(`<h2 id="dependency-information" tabindex="-1">Dependency information <a class="header-anchor" href="#dependency-information" aria-label="Permalink to &quot;Dependency information&quot;">​</a></h2><p>Dependencies are represented in LuaRocks through strings with a package name followed by a comma-separated list of constraints. Each constraint consists of an operator and a version number. In this string format, version numbers are represented as naturally as possible, like they are used by upstream projects (e.g. &quot;2.0beta3&quot;). Internally, LuaRocks converts them to a purely numeric representation, allowing comparison following some common sense heuristics. The precise specification of the comparison criteria is the source code of the luarocks.deps module, but the test/test_deps.lua file included with LuaRocks provides some insights on what these criteria are.</p><ul><li><strong>supported_platforms</strong> (array of strings) - If this array is not present, the rock is assumed to be portable to any platform. If present, this should contain strings containing LuaRocks platform identifiers, optionally preceded by a &quot;!&quot; to indicate a negative match. If only negative entries are listed, the rock is assumed to be portable to any platform except those listed. If any positive entry exists, then at least one entry must match positively to the currently running platform. Currently supported LuaRocks platform identifiers are: &quot;unix&quot;, &quot;windows&quot;, &quot;win32&quot;, &quot;cygwin&quot;, &quot;macosx&quot;, &quot;linux&quot;, &quot;freebsd&quot;. Platforms may have more than one valid identifier; e.g. Linux defines both &quot;unix&quot; and &quot;linux&quot;. Note that, as of 0.6, Cygwin under Windows defines {&quot;unix&quot;, &quot;cygwin&quot;} but <em>not</em> &quot;windows&quot;.</li><li><strong>dependencies</strong> (array of strings) - Each string represents a package this rock depends on, containing a package name followed by a comma-separated list of constraints. Example: <code>{&quot;lfs &gt;= 1.0, &amp;lt; 2.0&quot;}</code>. Accepted operators are the relational operators of Lua: <code>==</code> <code>~=</code> <code>&lt;</code> <code>&gt;</code> <code>&lt;=</code> <code>&gt;=</code> , as well as a special operator, <code>~&gt;</code>, inspired by the &quot;pessimistic operator&quot; of RubyGems (<code>&quot;~&gt; 2&quot;</code> means <code>&quot;&gt;= 2, &lt; 3&quot;</code>; <code>&quot;~&gt; 2.4&quot;</code> means <code>&quot;&gt;= 2.4, &lt; 2.5&quot;</code>). The absence of an operator means an implicit <code>==</code> (i.e., <code>&quot;lfs 1.0&quot;</code> is the same as <code>&quot;lfs == 1.0&quot;</code>). &quot;lua&quot; is an special dependency name; it matches not a rock, but the version of Lua in use. Supports <a href="./platform_overrides.html">per-platform overrides</a>.</li><li><strong>build_dependencies</strong> (array of strings) (since 3.0) - Dependencies that apply at build-time only, but not when installing binary (<code>.&lt;platform&gt;.rock</code>) or pure-Lua (<code>.all.rock</code>) rocks. Each string represents a package this rock depends on at build time, containing a package name followed by a comma-separated list of constraints. The syntax in the same as the <code>dependencies</code> field. Supports <a href="./platform_overrides.html">per-platform overrides</a>.</li><li><strong>external_dependencies</strong> (table) - For each key in the external_dependencies table in the rockspec file, four variables available to the build rules are created: <i>key</i>_DIR, <i>key</i>_BINDIR, <i>key</i>_INCDIR and <i>key</i>_LIBDIR. These are not overwritten if already set (e.g. by the LuaRocks config file or through the command-line). The base prefix for these can be given explicitly setting <i>key</i>_DIR in the config file or through the command-line, or implicitly, defaulting to the value of default_external_deps_dir, set in the config file. Values in the external_dependencies table are tables that may contain a &quot;header&quot; or a &quot;library&quot; field, with filenames to be tested for existence. Example: <code>{ EXPAT = { header = &quot;expat.h&quot; } }</code> -- on Unix, this will check that EXPAT_DIR/include/expat.h exists and will create variables accordingly. You can also use platform overrides or specify files of external dependencies in a <a href="./platform_agnostic_external_dependencies.html">platform-agnostic manner</a>. Supports <a href="./platform_overrides.html">per-platform overrides</a>.</li><li><strong>test_dependencies</strong> (array of strings) (since 3.0) - Dependencies that apply at test-time only, that is, only needed when running <code>luarocks test</code>. Each string represents a package this rock depends on at test time, containing a package name followed by a comma-separated list of constraints. The syntax in the same as the <code>dependencies</code> field. Supports <a href="./platform_overrides.html">per-platform overrides</a>.</li></ul><h2 id="build-rules" tabindex="-1">Build rules <a class="header-anchor" href="#build-rules" aria-label="Permalink to &quot;Build rules&quot;">​</a></h2><ul><li><strong>source</strong> (table, mandatory field) - Contains information on how to fetch sources to build this rock. Supports <a href="./platform_overrides.html">per-platform overrides</a>. <ul><li><strong>source.url</strong> (string, mandatory field) - the URL of the package source archive. Examples: &quot;<a href="https://github.com/keplerproject/wsapi/archive/v1.3.4.tar.gz" target="_blank" rel="noreferrer">https://github.com/keplerproject/wsapi/archive/v1.3.4.tar.gz</a>, &quot;git://github.com/keplerproject/wsapi.git&quot;. Note that this field is ignored when running <a href="./luarocks_make.html">luarocks make</a>, which uses the sources from your current directory instead. Different protocols are supported: <ul><li><code>cvs://</code> - for the CVS source control manager</li><li><code>file://</code> - for URLs in the local filesystem to archive file (note that for Unix paths, the root slash is the third slash, resulting in paths like <code>&quot;file:///full/path/filename&quot;</code>)</li><li><code>ftp://</code> - for FTP URLs to archive file</li><li><code>git://</code> - for the Git source control manager</li><li><code>git+file://</code> - for the Git source control manager when using repositories that need file:// URLs</li><li><code>git+http://</code> - for the Git source control manager when using repositories that need http:// URLs</li><li><code>git+https://</code> - for the Git source control manager when using repositories that need https:// URLs</li><li><code>git+ssh://</code> - for the Git source control manager when using repositories that need SSH login, such as <code>git@example.com/myrepo</code></li><li><code>hg://</code> - for the Mercurial source control manager</li><li><code>hg+http://</code> - for the Mercurial source control manager using repositories that need http:// URLs</li><li><code>hg+https://</code> - for the Mercurial source control manager using repositories that need https:// URLs</li><li><code>hg+ssh://</code> - for the Mercurial source control manager using repositories that need SSH login</li><li><code>http://</code> - for HTTP URLs to archive file</li><li><code>https://</code> - for HTTPS URLs to archive file</li><li><code>sscm://</code> - for the SurroundSCM source control manager</li><li><code>svn://</code> - for the Subversion source control manager</li><li><strong>Important:</strong> A source control manager URL cannot start with <code>http://</code> <code>https://</code>, <code>ftp://</code> or <code>file://</code>. For example, <code>https://github.com/keplerproject/wsapi.git</code> is incorrect, even though it works perfectly fine with <code>git clone</code>. The correct one is <code>git+https://github.com/keplerproject/wsapi.git</code>. Also note that only for GitHub URLs <code>git://</code> is being automatically handled internally as if it was <code>git+https://</code>. This is due to preserve backwards compatibility while still working with <a href="https://github.blog/security/application-security/improving-git-protocol-security-github/" target="_blank" rel="noreferrer">GitHub&#39;s increased default security</a> measures in blocking insecure connection types.</li></ul></li><li><strong>source.md5</strong> (string) - the MD5 sum for the source archive. Example: &quot;9ca22fd9f9413b54802d3d40b38c4e5c&quot;</li><li><strong>source.file</strong> (string) - the filename of the source archive. Can be omitted if it can be inferred from the <code>source.url</code> field. Example: &quot;luasocket-2.0.1.tar.gz&quot;</li><li><strong>source.dir</strong> (string) - the name of the directory created when the source archive is unpacked. Can be omitted if it can be inferred from the <code>source.file</code> field or if it can be inferred from the archive contents (i.e. the archive only contains a single directory with the sources). Example: &quot;luasocket-2.0.1&quot;</li><li><strong>source.tag</strong> (string) - for SCM-based URL protocols such as &quot;cvs://&quot; and &quot;git://&quot;, this field can be used to specify a tag for checking out sources. Example: &quot;HEAD&quot; (For compatibility reasons, <code>source.cvs_tag</code> is also accepted.)</li><li><strong>source.branch</strong> (string) - for SCM-based URL protocols such as &quot;git://&quot;, this field can be used to specify a branch for checking out sources. Example: &quot;v1.0&quot;</li><li><strong>source.module</strong> (string) - for SCM-based URL protocols such as &quot;cvs://&quot; and &quot;git://&quot;, this field can be used to specify the module to be checked out. Can be omitted if it is the same as the basename of the <code>source.url</code> field. Example: &quot;cgilua&quot; (For compatibility reasons, <code>source.cvs_module</code> is also accepted.)</li></ul></li><li><strong>build</strong> (table) - Contains all information pertaining <em>how</em> to build a rock. Supports <a href="./platform_overrides.html">per-platform overrides</a>. <ul><li><strong>build.type</strong> (string) - The LuaRocks build back-end to use. Example: &quot;make&quot;</li><li><strong>build.install</strong> (table) - For packages which don&#39;t provide means to install modules and expect the user to copy the .lua or library files by hand to the proper locations. This table contains categories of files. Each category is itself a table, where the array part is a list of filenames to be copied. For module directories only, in the hash part, other keys are identifiers in Lua module format, to indicate which subdirectory the file should be copied to. For example, <code>build.install.lua = {[&quot;foo.bar&quot;] = &quot;src/bar.lua&quot;}</code> will copy src/bar.lua to the foo directory under the rock&#39;s Lua files directory. The available categories are: <ul><li><strong>build.install.lua</strong> (table) - Lua modules written in Lua.</li><li><strong>build.install.lib</strong> (table) - Dynamic libraries implemented compiled Lua modules.</li><li><strong>build.install.conf</strong> (table) - Configuration files.</li><li><strong>build.install.bin</strong> (table) - Lua command-line scripts.</li></ul></li><li><strong>build.copy_directories</strong> (array of strings) (since 1.0) - A list of directories in the source directory to be copied to the rock installation prefix as-is. Useful for installing documentation and other files such as samples and tests. Default is {&quot;doc&quot;} for documentation to be locally installed in the rocktree. <ul><li>⚠️ <strong>Warning:</strong> - do not use the following directory names: &quot;lua&quot;, &quot;lib&quot;, &quot;rock_manifest&quot; or the name of your rockspec; those names are used by the .rock format internally, and attempting to copy directories with those names using the build.copy_directories directive will cause a clash.</li></ul></li><li><strong>build.patches</strong> (table) - A rockspec can embed patches in unified diff (&quot;diff -u&quot;) format, which are applied prior to building the modules. Each entry in this table should contain a descriptive file name for the patch a the key, and the text of the patch as the value (typically, as a long string). The patch is applied from within the source.dir directory, and file names ignore the first directory level (in other word, patches are applied with the equivalent of &quot;patch -p 1&quot;). Keep in mind that the actual text of the patch cannot be indented. Example:</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>patches = {</span></span>
<span class="line"><span>   [&quot;lua51-support.diff&quot;] = [[</span></span>
<span class="line"><span>--- old/mymodule.c....</span></span>
<span class="line"><span>]]</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="build-back-ends" tabindex="-1">Build back-ends <a class="header-anchor" href="#build-back-ends" aria-label="Permalink to &quot;Build back-ends&quot;">​</a></h3><p>Build back-ends indicate how to build a package. Fields of the <code>build</code> table other than <code>build.type</code>, <code>build.platforms</code> and <code>build.install</code> are specific to the given type.</p><h4 id="builtin" tabindex="-1">builtin <a class="header-anchor" href="#builtin" aria-label="Permalink to &quot;builtin&quot;">​</a></h4><p>This is a mode for packages distributing pure Lua or simple C modules. All pathnames used are relative to <code>source.dir</code>. The goal is to allow module authors to specify compilation of their C code in a clean, simple and portable way.</p>`,10),e("ul",null,[e("li",null,[e("strong",null,"build.modules"),t(" (map) - A map in which keys are module names in the format normally used by the require() function, and values may be: "),e("ul",null,[e("li",null,"strings - pathnames of Lua files or C sources, for modules based on a single source file."),e("li",null,"array of strings - pathnames of C sources of a simple module written in C composed of multiple files."),e("li",null,[t("table - a table containing one or more fields: "),e("ul",null,[e("li",null,[e("strong",null,"build.sources"),t(" (array of strings) - the only mandatory field, pathnames of C sources.")]),e("li",null,[e("strong",null,"build.libraries"),t(" (array of strings) - external libraries to be linked.")]),e("li",{FOO:"bar,",USE_BLA:""},[e("strong",null,"build.defines"),t(" (array of strings) - a list of C defines. eg.")]),e("li",null,[e("strong",null,"build.incdirs"),t(" (array of strings) - directories to be added to the compiler's headers lookup directory list.")]),e("li",null,[e("strong",null,"build.libdirs"),t(" (array of strings) - directories to be added to the linker's library lookup directory list.")])])])])])],-1),a('<h4 id="make" tabindex="-1">make <a class="header-anchor" href="#make" aria-label="Permalink to &quot;make&quot;">​</a></h4><p>Indicates the package uses a Makefile.</p><ul><li><strong>build.makefile</strong> (string) - Makefile to be used. Default is &quot;Makefile&quot; on Unix variants and &quot;Makefile.win&quot; under Win32.</li><li><strong>build.build_target</strong> (string) - Default is &quot;&quot;.</li><li><strong>build.build_pass</strong> (boolean) - Whether to perform a make pass on the target indicated by <code>build.build_target</code>. Default is true (i.e., to run make).</li><li><strong>build.install_target</strong> (string) - Default is &quot;install&quot;.</li><li><strong>build.install_pass</strong> (boolean) - Whether to perform a make pass on the target indicated by <code>build.build_target</code>. Default is true (i.e., to run make).</li><li><strong>build.build_variables</strong> (table) - Assignments to be passed to make during the build pass. Default is {}.</li><li><strong>build.install_variables</strong> (table) - Assignments to be passed to make during the install pass. Default is {}.</li><li><strong>build.variables</strong> (table) - Assignments to be passed to make on both passes. Default is {}.</li></ul><p>Variables expected by this back-end to be provided by the configuration file are:</p><ul><li><strong>CC</strong> - Command to call the C compiler.</li><li><strong>CFLAGS</strong> - Flags to be passed to the C compiler. May be empty.</li><li><strong>LIBFLAG</strong> - Flag to be passed to the C compiler to instruct it to build a shared library.</li></ul><p>These are usually detected by the default configuration, but can be overridden by the <a href="./config_file_format.html">configuration file</a>. See also the &quot;Variables&quot; section of the <a href="./config_file_format.html">Config file format</a> specification for other path variables that are defined automatically, and the documentation on the <code>external_dependencies</code> entry above for variables that are automatically generated based on paths of external dependencies.</p><h4 id="cmake" tabindex="-1">cmake <a class="header-anchor" href="#cmake" aria-label="Permalink to &quot;cmake&quot;">​</a></h4><p>Indicates the package uses CMake for building.</p><ul><li><strong>build.cmake</strong> (string) - If given, its contents are used as the CMakeLists.txt file. If not given, it is assumed that the package provides a CMakeLists.txt file.</li><li><strong>build.variables</strong> (table) - Additional variables to be passed to CMake. Equals to calling CMake with attributes: <code>cmake -Dkey1=value1 -Dkey2=value2 ...</code></li></ul><p>Additionally you can specify these environment variables when calling LuaRocks:</p><ul><li><strong>CMAKE_MODULE_PATH</strong> - Tells CMake where to search for additional modules.</li><li><strong>CMAKE_INCLUDE_PATH</strong> - Path to desired include directory.</li><li><strong>CMAKE_LIBRARY_PATH</strong> - Path to libraries.</li></ul><h4 id="command" tabindex="-1">command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;command&quot;">​</a></h4><p>A simple backend called &quot;command&quot; is also provided, in which build commands are typed in directly in the rockspec file.</p><ul><li><strong>build.build_command</strong> (string) - Command to run to build the package.</li><li><strong>build.install_command</strong> (string) - Command to run to install the package.</li></ul><h4 id="none" tabindex="-1">none <a class="header-anchor" href="#none" aria-label="Permalink to &quot;none&quot;">​</a></h4><p>A null build back-end. Indicates that there is no build to perform.</p><h2 id="test-rules" tabindex="-1">Test rules <a class="header-anchor" href="#test-rules" aria-label="Permalink to &quot;Test rules&quot;">​</a></h2><ul><li><strong>test</strong> (table) - Contains all information pertaining how to test a rock. Supports <a href="./platform_overrides.html">per-platform overrides</a>.</li></ul><h3 id="test-back-ends" tabindex="-1">Test back-ends <a class="header-anchor" href="#test-back-ends" aria-label="Permalink to &quot;Test back-ends&quot;">​</a></h3><p>Test back-ends indicate how to test a package. Fields of the <code>test</code> table other than <code>test.type</code> and <code>test.platforms</code> are specific to the given type.</p><h4 id="busted" tabindex="-1">busted <a class="header-anchor" href="#busted" aria-label="Permalink to &quot;busted&quot;">​</a></h4><p>If <code>test.type</code> is not specified, this type is auto-detected if <code>.busted</code> is present in the root of the source tree.</p><ul><li><strong>test.flags</strong> (array of string) - Additional CLI flags to pass to Busted when running.</li></ul><h4 id="command-1" tabindex="-1">command <a class="header-anchor" href="#command-1" aria-label="Permalink to &quot;command&quot;">​</a></h4><p>If <code>test.type</code> is not specified, this type is auto-detected if a file called <code>test.lua</code> is present in the root of the source tree.</p><ul><li><strong>test.script</strong> (string) - Filename of a Lua script to run as a test. Only one of <code>script</code> or <code>command</code> should be passed.</li><li><strong>test.command</strong> (string) - Filename of a shell command to run as a test. Only one of <code>script</code> or <code>command</code> should be passed.</li><li><strong>test.flags</strong> (array of string) - Additional CLI flags to pass to either the script or command when running.</li></ul>',26)])])}const g=i(n,[["render",l]]);export{m as __pageData,g as default};
